window.docContents[21].resolve({"/part-5-applications/ch20-notes-and-bibliography/#ch20-notes-and-bibliography":{"contents":"Goldblatt closes Lectures on the Hyperreals with Chapter 20 (Notes on Topics and Literature), tracing nonstandard analysis from Leibniz, Euler, and Cauchy through Hewitt's 1948 hyperreal rings C(X)/M, Łoś's 1955 ultraproduct theorem, Robinson's 1960 breakthrough and 1966 monograph Non-standard Analysis, Luxemburg's 1962 Caltech lectures, Keisler's undergraduate calculus textbook, Loeb's 1975 measure theory, Nelson's 1977 Internal Set Theory, and applications to mathematical physics, economics, and stochastic differential equations.\n\nThe complete 41-entry annotated bibliography and theorem-by-theorem mapping between Goldblatt's 20 chapters and our 21 Lean 4 modules (59,556 lines, 0 sorrys, 0 custom axioms) are documented in COVERAGE.md and README.md.\n\n\n","context":"Lectures on the Hyperreals — Interactive Lean 4 & Spatial Edition\u0009Part V — Landmark Applications & Reading Guide","header":"5.5. Chapter 20: Historical Notes, Further Reading & Coverage Map","id":"/part-5-applications/ch20-notes-and-bibliography/#ch20-notes-and-bibliography"}});